StructuredTextModel.Text:
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:						HE_SMS
//	CREATOR:					William Veim
//	COMPANY:				Helgevold
// REQUIREMENTS: 		NX CPU (INCLUDED TLS)
//
// DESCRTIPTION: 	SMS control via RT100
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	 VERSION			DATE				SIGN						DESCRIPTION
//	1.0.0				07-04-2025		William Veim				Initial release
//	1.0.1				30-04-2025		Ruben Byman				Added Sts_ConnectionError
//	1.0.2				20-05-2025		Ruben Byman				Bug fixing receiver list making, trigging of FB to send SMS and message generation and timer between priorities
//	1.0.3				22-05-2025		Ruben Byman				Added emergency message
// 1.0.4				28-05-2025		Fredrik Bjerkenes			added angle bracket (>=) AlarmST upper bound. Also added step to initialize AlarmFound to false before entering FOR Loop. Rising edge to reset Alarmfound In Case Of RT100 Sms Done or SMS Error.
// 1.1.0				02-06-2025		Jan Magne Dybvik		Endret leting etter alarm og sending av SMS til state machine
// 1.1.1				10-06-2025		Jan Magne Dybvik		Add recieved message to Recive buffer
// 1.1.2				11-06-2025		Jan Magne Dybvik		Removed Old recive buffer logic. Changed parameter name from Cfg_Mode to Cfg_CheckInbox
// 1.1.3				11-06-2025		Jan Magne Dybvik		Edited logic for deletion of recieved message from stack
// 1.1.4				11-06-2025		Jan Magne Dybvik		Edited logic for alarm acknowledgement
// 1.1.5				11-06-2025		Jan Magne Dybvik		Added alarm index to sent message and retrives alarm index from recieved message
// 1.1.6				26-06-2025		Jan Magne Dyvbik		Added function to reset alarm escalation countdown when message is recieved
// 1.1.7				23-07-2025		Fredrik Bjerkenes			Case of Siren priority changed from alarmsend_Index to Int_alarm[AlarmSend_index].Sts_Alarm_Priority, Wrk_AlertStarted is now being reset if there no active alarms present. 
// 1.1.7				24-07-2025 		Fredrik Bjerkenes			Moved TON siren instance to outside of IF and removed IF.
// 1.1.8				15-09-2025 		William Veim				Not include process value if input value <>'' (Digital value)
// 1.1.9				17-09-2025 		William Veim				Not include cabinet if input value <>'' (Oxygen control)
// 1.1.9				17-09-2025 		William Veim				Not include TAG if input value <>'' (Oxygen control)
// 1.2.0				12-10-2025 		William Veim				Important bugfix night/day shift active check
// 1.2.1			    14-10-2025 		William Veim				Improvements acknowlegement (from SMS)
// 1.2.2			    17-10-2025 		William Veim				Added logic for deleting recived messages based on age
// 1.2.3			    31-10-2025 		William Veim				Bugfix SMS send and no corresponding reciver whit correct priority
// 1.2.3			    14-11-2025 		Fredrik Bjerkenes			Midlertidelig løsning linje 650
// 1.2.4			    17-11-2025 		Fredrik Bjerkenes			Line 456, Emergency SMS if longer than 60s, it goes infinitly to Case 0 until emergency sms is set to off manually. Fixed so if it failes 3 times it is set to false trough case 31
// 1.2.5			    20-01-2026 		William Veim				Alarm search - Added "SendOnlyDayTime" functionality
// 1.3.0			    20-01-2026 		William Veim				Added logic for priority of SMS notification based on most critical alarm
// 1.3.1				23-06-2026		Ruben Byman				Bugfix prioritized alarms
//	1.3.2				30.06.2026		William Veim				Removed unused varable and improvement replacing '00' & '+' to only look at first position
//	1.3.3				01.07.2026		Ruben Byman				Bugfix alarms not sent if not of higher priority than previous alarm or first in array

//================================================================================================================================

(*************************************************************************
 *	IMPORTING SYSTEM VARIABLES
 *************************************************************************)
 //Retrieves current clock from PLC
Time_Current := TruncTod(DT_TO_TOD(In:=GetTime()), _SEC);
Date_Current := GetTime();
Current_Date := DT_TO_DATE(GetTime());
DayOfWeek_Current:= GetDayOfWeek(In:=GetTime());
Wrk_TimeStamp :=CONCAT(In1:=CONCAT(In1:=DateToString(Current_Date), In2:=' '), In2:=DELETE(In:=TODToString(Time_Current), L:=13, P:=6));
// Get Interval Time
Wrk_TaskIntervalTime := GetMyTaskInterval();
 
(*************************************************************************
 *	INITIALISING VARIABELS
 *************************************************************************)
 
 //Clear alarm array at startup
 //Reset all used, all FB still in use will set alarm to "In use"
 IF Cfg_ClearArray THEN
	 Clear(Int_Alarm);
 END_IF;
 
 IF NOT Ext_Settings.INT_Data.Initialise THEN
	 
	 //Day shift parameter
	 Ext_Settings.EXT_Engineering.Cfg_DayShift_Delay:=10;
	 Ext_Settings.EXT_Engineering.Cfg_DayShift_DelayAcknowledged:=20;
	 Ext_Settings.EXT_Engineering.Cfg_DayShift_StartTime_Hour:=07;
	 Ext_Settings.EXT_Engineering.Cfg_DayShift_StartTime_Minute:=00;
	 Ext_Settings.EXT_Engineering.Cfg_DayShift_EndTime_Hour:=16;
	 Ext_Settings.EXT_Engineering.Cfg_DayShift_EndTime_Minute:=00;

	//Night shit parameter
	Ext_Settings.EXT_Engineering.Cfg_NightShift_Delay:=10;
	Ext_Settings.EXT_Engineering.Cfg_NightShift_DelayAcknowledged:=20;
	Ext_Settings.EXT_Engineering.Cfg_NightShift_StartTime_Hour:=16;
	Ext_Settings.EXT_Engineering.Cfg_NightShift_StartTime_Minute:=00;
	Ext_Settings.EXT_Engineering.Cfg_NightShift_EndTime_Hour:=07;
	Ext_Settings.EXT_Engineering.Cfg_NightShift_EndTime_Minute:=00;
	
	//Others
	Ext_Settings.EXT_Engineering.Cfg_SirenTime:=10;
	
	//Init complete
	Ext_Settings.INT_Data.Initialise:=TRUE;
	
 END_IF;
 
  (*************************************************************************
 *	VARIABLE CONTROL
  *************************************************************************)
 
//DAY SHIFT
//------------

 //End time is before midnight
 IF HE_INT2TOD(Hour:=Ext_Settings.EXT_Engineering.Cfg_DayShift_StartTime_Hour, Minute:=Ext_Settings.EXT_Engineering.Cfg_DayShift_StartTime_Minute) < HE_INT2TOD(Hour:=Ext_Settings.EXT_Engineering.Cfg_DayShift_EndTime_Hour, Minute:=Ext_Settings.EXT_Engineering.Cfg_DayShift_EndTime_Minute) THEN
	 
	Ext_Settings.EXT_Engineering.Sts_DayShift_Active:= Time_Current >= HE_INT2TOD(Hour:=Ext_Settings.EXT_Engineering.Cfg_DayShift_StartTime_Hour, Minute:=Ext_Settings.EXT_Engineering.Cfg_DayShift_StartTime_Minute) AND Time_Current < HE_INT2TOD(Hour:=Ext_Settings.EXT_Engineering.Cfg_DayShift_EndTime_Hour, Minute:=Ext_Settings.EXT_Engineering.Cfg_DayShift_EndTime_Minute);

//End time is after midtnight
 ELSE
	 Ext_Settings.EXT_Engineering.Sts_DayShift_Active:= Time_Current >= HE_INT2TOD(Hour:=Ext_Settings.EXT_Engineering.Cfg_DayShift_StartTime_Hour, Minute:=Ext_Settings.EXT_Engineering.Cfg_DayShift_StartTime_Minute) AND Time_Current < HE_INT2TOD(Hour:=Ext_Settings.EXT_Engineering.Cfg_DayShift_EndTime_Hour, Minute:=Ext_Settings.EXT_Engineering.Cfg_DayShift_EndTime_Minute);
 END_IF;
 
  //NIGHT SHIFT
 //---------------
 
 //End time is lower than start time (ex: Start 16:00, end 08:00). 
 IF HE_INT2TOD(Hour:=Ext_Settings.EXT_Engineering.Cfg_NightShift_StartTime_Hour, Minute:=Ext_Settings.EXT_Engineering.Cfg_NightShift_StartTime_Minute) < HE_INT2TOD(Hour:=Ext_Settings.EXT_Engineering.Cfg_NightShift_EndTime_Hour, Minute:=Ext_Settings.EXT_Engineering.Cfg_NightShift_EndTime_Minute) THEN
	 
	Ext_Settings.EXT_Engineering.Sts_NightShift_Active:= Time_Current >= HE_INT2TOD(Hour:=Ext_Settings.EXT_Engineering.Cfg_NightShift_StartTime_Hour, Minute:=Ext_Settings.EXT_Engineering.Cfg_NightShift_StartTime_Minute) AND Time_Current < HE_INT2TOD(Hour:=Ext_Settings.EXT_Engineering.Cfg_NightShift_EndTime_Hour, Minute:=Ext_Settings.EXT_Engineering.Cfg_NightShift_EndTime_Minute);
	
//End time is bigger than start time (ex: Start 16:00, end 18:00).
 ELSE
	 Ext_Settings.EXT_Engineering.Sts_NightShift_Active:= Time_Current >= HE_INT2TOD(Hour:=Ext_Settings.EXT_Engineering.Cfg_NightShift_StartTime_Hour, Minute:=Ext_Settings.EXT_Engineering.Cfg_NightShift_StartTime_Minute) OR Time_Current < HE_INT2TOD(Hour:=Ext_Settings.EXT_Engineering.Cfg_NightShift_EndTime_Hour, Minute:=Ext_Settings.EXT_Engineering.Cfg_NightShift_EndTime_Minute);
 END_IF;
 
 (*************************************************************************
 *	ALARM CHECK AND TIME COUNTDOWN
 *************************************************************************)
 
 //Check usage of alarm array
 Wrk_AlarmArrayOutOfRange := Wrk_NumberAlarmUsed >= SizeOfAry(Int_Alarm);
 
 //Count down timer between priorities and looks for active alarm
Wrk_NumAlarmActive:=0;
Wrk_NumAlarmAck:=0;
Wrk_NumberAlarmUsed:=0;
Wrk_AlarmSearch_HighestPri:=-1;
Wrk_AlarmPriority_Ranked:=-1;
Wrk_LB:=DINT_TO_UINT(LOWER_BOUND(Int_Alarm, 1));
Wrk_UB:=DINT_TO_UINT(UPPER_BOUND(Int_Alarm, 1));
 
FOR Wrk_LoopIndex := Wrk_LB TO Wrk_UB DO
 
	  //COUNT NUMBER OF ALARMS IN USE
	IF Int_Alarm[Wrk_LoopIndex].Cfg_InUse THEN
		Inc(Wrk_NumberAlarmUsed);
	END_IF;
	 
	FOR Wrk_AlarmSearch:= DINT_TO_UINT(LOWER_BOUND(Int_Alarm[Wrk_LoopIndex].Sts_AlarmData, 1)) TO DINT_TO_UINT(UPPER_BOUND(Int_Alarm[Wrk_LoopIndex].Sts_AlarmData, 1)) DO
	 
		//COUNT DOWN TIME TO NEXT
		IF Int_Alarm[Wrk_LoopIndex].Cfg_InUse AND Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_TimeToNextPri > TIME#0s AND Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_AlarmState > 0 THEN
			Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_TimeToNextPri := SUB_TIME(In1:=Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_TimeToNextPri, In2:=Wrk_TaskIntervalTime);
		ELSE
			Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_TimeToNextPri := TIME#0s;
		END_IF;
		 
		//COUNT NUMBER OF ALARMS
		IF Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_AlarmState > 0 AND Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_AlarmState <> 10 THEN
			Inc(Wrk_NumAlarmActive);
		END_IF;
		 
		IF Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_AlarmState = 10 THEN
			Inc(Wrk_NumAlarmAck);
		END_IF;
				
		//LOOK FOR ACTIVE ALARMS		
		IF  Int_Alarm[Wrk_LoopIndex].Cfg_InUse //Alarm is in use
			AND Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_AlarmState > 0 //Sate above idle/standby
			AND Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_AlarmState < 6 //State under "sending complete"
			AND Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_TimeToNextPri = TIME#0s //Time to next sending equal zero
			AND (Int_Alarm[Wrk_LoopIndex].Sts_SMS_OnlyDayTime AND Ext_Settings.EXT_Engineering.Sts_DayShift_Active //Only send SMS in daytime/day shift, and day shift active
			OR NOT Int_Alarm[Wrk_LoopIndex].Sts_SMS_OnlyDayTime) THEN //Send SMS anytime
				
				CASE Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_Priority OF 
					
					6: 
					Wrk_AlarmPriority_Ranked:=0;//Good
					
					0: 
					Wrk_AlarmPriority_Ranked:=1;//Diagnostic
					
					1: 
					Wrk_AlarmPriority_Ranked:=2;//Low
					
					2: 
					Wrk_AlarmPriority_Ranked:=3;//Medium (not in use)
					
					3: 
					Wrk_AlarmPriority_Ranked:=4;//High
					
					4: 
					Wrk_AlarmPriority_Ranked:=5;//Critical
					
				END_CASE;
		END_IF;
				
		IF Wrk_AlarmPriority_Ranked > Wrk_AlarmSearch_HighestPri THEN
			Wrk_AlarmSearch_HighestPri := Wrk_AlarmPriority_Ranked;
			CASE Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_AlarmState OF 
				 
				0: //Alarm initial/idle state
					;
				 
				1: //Alarm active, not sent
					Wrk_AlarmSend_Found:=TRUE;
					Wrk_AlarmSend_Index:=Wrk_LoopIndex;
					Wrk_AlarmSend_Number:=Wrk_AlarmSearch;
					Wrk_AlarmSend_Priority:=1;
				 
				2: //Alarm sendt to pri 1
						Wrk_AlarmSend_Found:=TRUE;
						Wrk_AlarmSend_Index:=Wrk_LoopIndex;
						Wrk_AlarmSend_Number:=Wrk_AlarmSearch;
						Wrk_AlarmSend_Priority:=2;
				 
				 3: //Alarm sendt to pri 2
						Wrk_AlarmSend_Found:=TRUE;
						Wrk_AlarmSend_Index:=Wrk_LoopIndex;
						Wrk_AlarmSend_Number:=Wrk_AlarmSearch;
						Wrk_AlarmSend_Priority:=3;
				 
				4: //Alarm sendt to pri 3
						Wrk_AlarmSend_Found:=TRUE;
						Wrk_AlarmSend_Index:=Wrk_LoopIndex;
						Wrk_AlarmSend_Number:=Wrk_AlarmSearch;
						Wrk_AlarmSend_Priority:=4;
				 
				5: //Alarm sendt to pri 4
						Wrk_AlarmSend_Found:=TRUE;
						Wrk_AlarmSend_Index:=Wrk_LoopIndex;
						Wrk_AlarmSend_Number:=Wrk_AlarmSearch;
						Wrk_AlarmSend_Priority:=5;
			END_CASE;
		END_IF;
		  
		  //LOOK FOR RETURNED ALARM - Send return notification if enabled
		IF NOT Wrk_AlarmReturn_Found
			AND Int_Alarm[Wrk_LoopIndex].Cfg_InUse //Alarm in use
			AND Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_AlarmState = 0 //Sate idle/standby
			AND Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_ReturnMessage THEN 
				Wrk_AlarmReturn_Found:=		TRUE;
				Wrk_AlarmReturn_Index:=		Wrk_LoopIndex;
				Wrk_AlarmReturn_Number:=	Wrk_AlarmSearch;
				Int_Alarm[Wrk_LoopIndex].Sts_AlarmData[Wrk_AlarmSearch].SMS_ReturnMessage:=FALSE;
		END_IF;
			
	 END_FOR;
END_FOR;
 
 (*************************************************************************
 *	STATE MACHINE - STATE FOR SENDING SMS
 *************************************************************************) 
 
 CASE Wrk_State OF
	 
	 
  (*************************************************************************
	*	IDLE STATE / STANDBY
   *************************************************************************) 
	 0: 
 
		 IF Wrk_AlarmSend_Found THEN //Send alarm messase
			 Wrk_State:=1;
			 Wrk_TimeInState := T#0s;
		 ELSIF Ext_Settings.EXT_Operator.Cfg_Emergency_Send THEN //Send emergency message
			 Wrk_State:=2;
			 Wrk_TimeInState := T#0s;		 
		 ELSIF Wrk_SendAcknMessage THEN //Send acknowlegdement sucsess message
			 Wrk_State:=3;
			 Wrk_TimeInState := T#0s;
		 ELSIF Wrk_AlarmReturn_Found THEN //Send alarm returned message
			 Wrk_State:=4;
			 Wrk_TimeInState := T#0s;
		 END_IF; 
 
   (*************************************************************************
	*	ALARM MESSAGE - BUILD SEND LIST AND MESSAGE
   *************************************************************************) 
 	1:
		 Clear(Wrk_SMS_Message);
		 Clear(Wrk_SMS_SendBuffer_PhoneNumber);
		 Clear(Wrk_SMS_SendBuffer_Pos);
		 
		//DECODING ALARM PRIORITY
		//--------------------------------
		 CASE Int_Alarm[Wrk_AlarmSend_Index].Sts_AlarmData[Wrk_AlarmSend_Number].SMS_Priority OF
			 
			 0: //Diagnostic
			 Wrk_AlarmPriority:='Diagnostic';
			 
			 1://Low
			 Wrk_AlarmPriority:='Low';
			 
			 2://Medium
			 Wrk_AlarmPriority:='Medium';
			 
			 3://High
			 Wrk_AlarmPriority:='High';
			 
			 4://Critical
			 Wrk_AlarmPriority:='Critical';
			 
			 5://Low
			 Wrk_AlarmPriority:='Simulating';
			 
			 6://Good
			 Wrk_AlarmPriority:='Good';
		 END_CASE;
		 
		 //GENERATING RECIVER LIST
		 //------------------------------
		 
		 //Looking through contacts - Checking that each contact is active, priority equal alarm priority, number is valid. And that revice location (on contact) is found in current alarm.
		  	Wrk_LB:=DINT_TO_UINT(LOWER_BOUND(Ext_Contacts, 1));
 			Wrk_UB:=DINT_TO_UINT(UPPER_BOUND(Ext_Contacts, 1));
			FOR Wrk_SendList_Contacts_Index:=Wrk_LB TO  Wrk_UB DO //For loop to check all contacts
				
					IF Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_Active //Current contact is active (based on current day, night/day etc etc) 
						AND Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_Priority = Wrk_AlarmSend_Priority //Current position/contact corresponds to priority for current alarm send state
						AND Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber <> ''  THEN //Current position/contact is used
						
							//Each contact can be set to recive alarms from multiple locations, aswell as an alarm can be set to multiple locations (simple as it sounds, it is not)
							FOR Wrk_SendList_LocationLookUp := DINT_TO_UINT(LOWER_BOUND(Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation,1)) TO DINT_TO_UINT(UPPER_BOUND(Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation,1)) DO
									IF 		  (Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] = Int_Alarm[Wrk_AlarmSend_Index].Sts_Location[0] AND Int_Alarm[Wrk_AlarmSend_Index].Sts_Location[0] > 0 AND Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] > 0) //Index 0 = Not configured
										OR (Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] = Int_Alarm[Wrk_AlarmSend_Index].Sts_Location[1] AND Int_Alarm[Wrk_AlarmSend_Index].Sts_Location[1] > 0 AND Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] > 0) //Index 0 = Not configured
										OR (Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] = Int_Alarm[Wrk_AlarmSend_Index].Sts_Location[2] AND Int_Alarm[Wrk_AlarmSend_Index].Sts_Location[2] > 0 AND Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] > 0) //Index 0 = Not configured
										OR (Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] = Int_Alarm[Wrk_AlarmSend_Index].Sts_Location[3] AND Int_Alarm[Wrk_AlarmSend_Index].Sts_Location[3] > 0 AND Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] > 0) //Index 0 = Not configured
										OR (Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] = Int_Alarm[Wrk_AlarmSend_Index].Sts_Location[4] AND Int_Alarm[Wrk_AlarmSend_Index].Sts_Location[4] > 0 AND Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] > 0) //Index 0 = Not configured
										OR  Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] = 999	THEN //Code for recive all
										
											IF FIND(In1:=Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber, In2:='+') = 1 THEN
												Wrk_SMS_SendBuffer_PhoneNumber[Wrk_SMS_SendBuffer_Pos] := Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber;
												Wrk_SMS_SendBuffer_PhoneNumber[Wrk_SMS_SendBuffer_Pos] := REPLACE(In1:=Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber, In2:='%2b', L:=1, P:=1);
											ELSIF FIND(In1:=Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber, In2:='00') = 1 THEN
												Wrk_SMS_SendBuffer_PhoneNumber[Wrk_SMS_SendBuffer_Pos] := Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber;
												Wrk_SMS_SendBuffer_PhoneNumber[Wrk_SMS_SendBuffer_Pos] := REPLACE(In1:=Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber, In2:='%2b', L:=2, P:=1);
											ELSE
												Wrk_SMS_SendBuffer_PhoneNumber[Wrk_SMS_SendBuffer_Pos] := Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber;
											END_IF;
											
											Inc(Wrk_SMS_SendBuffer_Pos);
										
										EXIT;
									END_IF;
							END_FOR;
					END_IF;
			END_FOR;
		
		 //GENERATING ALARM MESSAGE
		 //-----------------------------------
		 
		 IF Int_Alarm[Wrk_AlarmSend_Index].Sts_Process_TAG <> '' THEN
		 	HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:=		Int_Alarm[Wrk_AlarmSend_Index].Sts_Process_TAG, In_Variable:=' , ', Cfg_Order:=FALSE); //Adds TAG (IF value is present)
		 END_IF;
		 
		 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='', 		In_Variable:=Int_Alarm[Wrk_AlarmSend_Index].Sts_Process_Desc, Cfg_Order:=FALSE); //Adds description
		 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:=' , ', 	In_Variable:=Int_Alarm[Wrk_AlarmSend_Index].Sts_AlarmData[Wrk_AlarmSend_Number].SMS_Suffix, Cfg_Order:=FALSE); //Adds suffix
		 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:=' $N', In_Variable:='$N', Cfg_Order:=FALSE);//Line shift
		 
		 IF Ext_Settings.EXT_Engineering.Cfg_SMS_Include_ProcessValue AND Int_Alarm[Wrk_AlarmSend_Index].Sts_Process_Value <> '' THEN //IF config to add process value (IF value is present)
		 	HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='Val: ', In_Variable:=Int_Alarm[Wrk_AlarmSend_Index].Sts_Process_Value, Cfg_Order:=FALSE); //Adds process value
			HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='', In_Variable:='$N', Cfg_Order:=FALSE);//Line shift
		 END_IF;	 
		 
		 IF Ext_Settings.EXT_Engineering.Cfg_SMS_Include_Priority THEN //IF config to add priority
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='Pri: ', In_Variable:=Wrk_AlarmPriority , Cfg_Order:=FALSE); //Adds priority
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='', In_Variable:='$N', Cfg_Order:=FALSE);//Line shift
		 END_IF;
		 		 
		 IF Ext_Settings.EXT_Engineering.Cfg_SMS_Include_ConnectedCabinet AND Int_Alarm[Wrk_AlarmSend_Index].Sts_Connected_Cabinet <> '' THEN //IF config to add connected cabinet (IF value is present)
		 	HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='Cab: ', In_Variable:=Int_Alarm[Wrk_AlarmSend_Index].Sts_Connected_Cabinet, Cfg_Order:=FALSE); //Adds connected cabinet
			HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='', In_Variable:='$N', Cfg_Order:=FALSE);//Line shift
		 END_IF;
		 
		 IF Ext_Settings.EXT_Engineering.Cfg_SMS_Include_ConnectedController AND Int_Alarm[Wrk_AlarmSend_Index].Sts_Connected_Controller <> '' THEN //IF config to add connected controller
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='CPU: ', In_Variable:=Int_Alarm[Wrk_AlarmSend_Index].Sts_Connected_Controller, Cfg_Order:=FALSE); //Adds connected controller
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='', In_Variable:='$N', Cfg_Order:=FALSE);//Line shift
		 END_IF;
		 
		 IF Ext_Settings.EXT_Engineering.Cfg_SMS_Include_TimeStamp THEN //IF config to add connected controller
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='Time: ', In_Variable:=Wrk_TimeStamp, Cfg_Order:=FALSE); //Adds timestamp
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='', In_Variable:='$N', Cfg_Order:=FALSE);//Line shift
		 END_IF;
		 
		 IF Ext_Settings.EXT_Engineering.Cfg_SMS_Include_Location THEN //IF config to add connected controller
			 
			 FOR LocationIndex_LookUp:= DINT_TO_UINT(LOWER_BOUND(Ext_Settings.EXT_Engineering.Location_Data,1)) TO DINT_TO_UINT(UPPER_BOUND(Ext_Settings.EXT_Engineering.Location_Data,1)) DO
				 IF Ext_Settings.EXT_Engineering.Location_Data[LocationIndex_LookUp].InUse AND Ext_Settings.EXT_Engineering.Location_Data[LocationIndex_LookUp].ID = Int_Alarm[Wrk_AlarmSend_Index].Sts_Location[0] THEN //Location array[0] is main location
					 LocationName:=		Ext_Settings.EXT_Engineering.Location_Data[LocationIndex_LookUp].Name;
					 EXIT;
				 END_IF;
			 END_FOR;
			 
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='Loc: ', In_Variable:= LocationName, Cfg_Order:=FALSE); //Adds connected location
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='', In_Variable:='$N', Cfg_Order:=FALSE);//Line shift
		 END_IF;
		 
		 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='Al: ', In_Variable:= NumToDecString(In:=Wrk_AlarmSend_Index, L:=3, Fill:=_ZERO)  , Cfg_Order:=FALSE); //Adds alarm number
			 
		 // Trigger Send SMS
		 IF NOT FB_RT100_SMS.Sts_SendSMSBusy AND Wrk_SMS_Message<>'' AND  Wrk_SMS_SendBuffer_PhoneNumber[0] <>'' THEN
			 Wrk_State := 20;
			 Wrk_TimeInState := T#0s;
			 FB_RT100_SMS.Inp_SendSMS := TRUE;
		
		//No message generated, or no reciver found
		 ELSIF Wrk_SMS_Message='' OR  Wrk_SMS_SendBuffer_PhoneNumber[0] = '' THEN
			 Wrk_State := 31;
			 Wrk_TimeInState := T#0s;
			 
		 // State Timeout
		 ELSIF Wrk_TimeInState > T#60s THEN
			 Wrk_State := 31;
			 Wrk_TimeInState := T#0s;
		 END_IF;	 	 
	
   (**************************************************************************
	*	EMERGENCY MESSAGE - COPY MESSAGE AND BUILD RECIVER LIST
   **************************************************************************) 
 	2: 
		 Clear(Wrk_SMS_Message);
		 Clear(Wrk_SMS_SendBuffer_PhoneNumber);
		 Clear(Wrk_SMS_SendBuffer_Pos);
		 
		//GENERATING RECIVER LIST
	 	//------------------------------
		
		FOR Wrk_Contact_Index := 0 TO DINT_TO_UINT(UPPER_BOUND(Ext_Contacts, 1)) DO
			
			IF Ext_Contacts[Wrk_Contact_Index].Cfg_PhoneNumber <> '' THEN
				
				//Replace "+" or "00" eith "%2b" berfore merging (to work with GateManager)
				IF FIND(In1:=Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber, In2:='+') = 1 THEN
					Wrk_SMS_SendBuffer_PhoneNumber[Wrk_SMS_SendBuffer_Pos] := REPLACE(In1:=Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber, In2:='%2b', L:=1, P:=1);
				ELSIF FIND(In1:=Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber, In2:='00') = 1 THEN
					Wrk_SMS_SendBuffer_PhoneNumber[Wrk_SMS_SendBuffer_Pos] := REPLACE(In1:=Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber, In2:='%2b', L:=2, P:=1);
				ELSE
					Wrk_SMS_SendBuffer_PhoneNumber[Wrk_SMS_SendBuffer_Pos] := Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber;
				END_IF;
				
				Inc(Wrk_SMS_SendBuffer_Pos);

			END_IF;
		END_FOR;

		//GENERATING ALARM MESSAGE
	 	//-----------------------------------
		Wrk_SMS_Message := Ext_Settings.EXT_Operator.Cfg_Emergency_Message;

		 // Trigger Send SMS
		 IF NOT FB_RT100_SMS.Sts_SendSMSBusy AND Wrk_SMS_Message<>'' AND  Wrk_SMS_SendBuffer_PhoneNumber[0] <>'' THEN
			 Wrk_State := 20;
			 Wrk_TimeInState := T#0s;
			 FB_RT100_SMS.Inp_SendSMS := TRUE;
			
		//No message generated, or no reciver found
		 ELSIF Wrk_SMS_Message='' OR  Wrk_SMS_SendBuffer_PhoneNumber[0] = '' THEN
			 Wrk_State := 31;
			 Wrk_TimeInState := T#0s;	
			
		 // State Timeout
		 ELSIF Wrk_TimeInState > T#60s THEN
			 Wrk_State := 31;
			 Wrk_TimeInState := T#0s;
		 END_IF;	
	
   (**************************************************************************
	*	ACKNOWLEGDEMENT MESSAGE - BUILD SEND LIST AND MESSAGE
   **************************************************************************) 
 	3: 
		 Clear(Wrk_SMS_Message);
		 Clear(Wrk_SMS_SendBuffer_PhoneNumber);
		 Clear(Wrk_SMS_SendBuffer_Pos);
		 
		//GENERATING RECIVER LIST
		//------------------------------
		Wrk_SMS_SendBuffer_PhoneNumber[0]:=Wrk_SendAcknMessage_Number; 
	
		//GENERATING ALARM MESSAGE
		//-----------------------------------
		Wrk_SMS_Message :=Wrk_SendAcknMessage_Message;
	
		 // Trigger Send SMS
		 IF NOT FB_RT100_SMS.Sts_SendSMSBusy AND Wrk_SMS_Message<>'' AND  Wrk_SMS_SendBuffer_PhoneNumber[0] <>'' THEN
			 Wrk_State := 20;
			 Wrk_TimeInState := T#0s;
			 FB_RT100_SMS.Inp_SendSMS := TRUE;
			
		 //No message generated, or no reciver found
		 ELSIF Wrk_SMS_Message='' OR  Wrk_SMS_SendBuffer_PhoneNumber[0] = '' THEN
			 Wrk_State := 31;
			 Wrk_TimeInState := T#0s;		
			
		 // State Timeout
		 ELSIF Wrk_TimeInState > T#60s THEN
			 Wrk_State := 31;
			 Wrk_TimeInState := T#0s;
		 END_IF;	 
	
	(**************************************************************************
	*	ALARM RETURN NOTIFICATION - BUILD MESSAGE AND SEND LIST
    **************************************************************************) 
	 4: 
		
		 Clear(Wrk_SMS_Message);
		 Clear(Wrk_SMS_SendBuffer_PhoneNumber);
		 Clear(Wrk_SMS_SendBuffer_Pos);
		 
		 //GENERATING RECIVER LIST
		 //------------------------------
		 
		 //Looking through contacts - Checking that each contact is active, priority equal alarm priority, number is valid. And that revice location (on contact) is found in current alarm.
		  	Wrk_LB:=DINT_TO_UINT(LOWER_BOUND(Ext_Contacts, 1));
 			Wrk_UB:=DINT_TO_UINT(UPPER_BOUND(Ext_Contacts, 1));
			FOR Wrk_SendList_Contacts_Index:=Wrk_LB TO  Wrk_UB DO //For loop to check all contacts
				
					IF Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_Active //Current contact is active (based on current day, night/day etc etc) 
						AND Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber <> ''  THEN //Current position/contact is used
						
							//Each contact can be set to recive alarms from multiple locations, aswell as an alarm can be set to multiple locations (simple as it sounds, it is not)
							FOR Wrk_SendList_LocationLookUp := DINT_TO_UINT(LOWER_BOUND(Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation,1)) TO DINT_TO_UINT(UPPER_BOUND(Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation,1)) DO
									IF 		  (Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] = Int_Alarm[Wrk_AlarmReturn_Index].Sts_Location[0] AND Int_Alarm[Wrk_AlarmReturn_Index].Sts_Location[0] > 0 AND Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] > 0) //Index 0 = Not configured
										OR (Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] = Int_Alarm[Wrk_AlarmReturn_Index].Sts_Location[1] AND Int_Alarm[Wrk_AlarmReturn_Index].Sts_Location[1] > 0 AND Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] > 0) //Index 0 = Not configured
										OR (Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] = Int_Alarm[Wrk_AlarmReturn_Index].Sts_Location[2] AND Int_Alarm[Wrk_AlarmReturn_Index].Sts_Location[2] > 0 AND Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] > 0) //Index 0 = Not configured
										OR (Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] = Int_Alarm[Wrk_AlarmReturn_Index].Sts_Location[3] AND Int_Alarm[Wrk_AlarmReturn_Index].Sts_Location[3] > 0 AND Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] > 0) //Index 0 = Not configured
										OR (Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] = Int_Alarm[Wrk_AlarmReturn_Index].Sts_Location[4] AND Int_Alarm[Wrk_AlarmReturn_Index].Sts_Location[4] > 0 AND Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] > 0) //Index 0 = Not configured
										OR  Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_ReceiveLocation[Wrk_SendList_LocationLookUp] = 999	THEN //Code for recive all
										
											IF FIND(In1:=Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber, In2:='+') = 1 THEN
												Wrk_SMS_SendBuffer_PhoneNumber[Wrk_SMS_SendBuffer_Pos] := Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber;
												Wrk_SMS_SendBuffer_PhoneNumber[Wrk_SMS_SendBuffer_Pos] := REPLACE(In1:=Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber, In2:='%2b', L:=1, P:=1);
											ELSIF FIND(In1:=Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber, In2:='00') = 1 THEN
												Wrk_SMS_SendBuffer_PhoneNumber[Wrk_SMS_SendBuffer_Pos] := Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber;
												Wrk_SMS_SendBuffer_PhoneNumber[Wrk_SMS_SendBuffer_Pos] := REPLACE(In1:=Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber, In2:='%2b', L:=2, P:=1);
											ELSE
												Wrk_SMS_SendBuffer_PhoneNumber[Wrk_SMS_SendBuffer_Pos] := Ext_Contacts[Wrk_SendList_Contacts_Index].Cfg_PhoneNumber;
											END_IF;
											
											Inc(Wrk_SMS_SendBuffer_Pos);
										
										EXIT;
									END_IF;
							END_FOR;
					END_IF;
			END_FOR;
		 
		 //DECODING ALARM PRIORITY
		//--------------------------------
		 CASE Int_Alarm[Wrk_AlarmReturn_Index].Sts_AlarmData[Wrk_AlarmReturn_Number].SMS_Priority OF
			 
			 0: //Diagnostic
			 Wrk_AlarmPriority:='Diagnostic';
			 
			 1://Low
			 Wrk_AlarmPriority:='Low';
			 
			 2://Medium
			 Wrk_AlarmPriority:='Medium';
			 
			 3://High
			 Wrk_AlarmPriority:='High';
			 
			 4://Critical
			 Wrk_AlarmPriority:='Critical';
			 
			 5://Low
			 Wrk_AlarmPriority:='Simulating';
			 
			 6://Good
			 Wrk_AlarmPriority:='Good';
		 END_CASE;
		 
		 //GENERATING ALARM MESSAGE
		 //-----------------------------------
		 
		 IF Int_Alarm[Wrk_AlarmReturn_Index].Sts_Process_TAG <> '' THEN
		 	HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:=Int_Alarm[Wrk_AlarmReturn_Index].Sts_Process_TAG, In_Variable:=' , '); //Adds TAG (IF value is present)
		 END_IF;
		 
		 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='', In_Variable:=Int_Alarm[Wrk_AlarmReturn_Index].Sts_Process_Desc); //Adds description
		 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:=' , ', In_Variable:=Int_Alarm[Wrk_AlarmReturn_Index].Sts_AlarmData[Wrk_AlarmReturn_Number].SMS_Suffix); //Adds suffix
		 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:=' , ', In_Variable:='Alarm returned'); //Adds information
		 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:=' $N', In_Variable:='$N');//Double line shift
		 
		 IF Ext_Settings.EXT_Engineering.Cfg_SMS_Include_ProcessValue AND Int_Alarm[Wrk_AlarmReturn_Index].Sts_Process_Value <> '' THEN //IF config to add process value (IF value is present)
		 	HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='Val: ', In_Variable:=Int_Alarm[Wrk_AlarmReturn_Index].Sts_Process_Value); //Adds process value
			HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='', In_Variable:='$N');//Line shift
		 END_IF;	 
		 
		 IF Ext_Settings.EXT_Engineering.Cfg_SMS_Include_Priority THEN //IF config to add priority
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='Pri: ', In_Variable:=Wrk_AlarmPriority); //Adds priority
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='', In_Variable:='$N');//Line shift
		 END_IF;
		 		 
		 IF Ext_Settings.EXT_Engineering.Cfg_SMS_Include_ConnectedCabinet AND Int_Alarm[Wrk_AlarmReturn_Index].Sts_Connected_Cabinet <> '' THEN //IF config to add connected cabinet (IF value is present)
		 	HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='Cab: ', In_Variable:=Int_Alarm[Wrk_AlarmReturn_Index].Sts_Connected_Cabinet); //Adds connected cabinet
			HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='', In_Variable:='$N');//Line shift
		 END_IF;
		 
		 IF Ext_Settings.EXT_Engineering.Cfg_SMS_Include_ConnectedController AND Int_Alarm[Wrk_AlarmReturn_Index].Sts_Connected_Controller <> '' THEN //IF config to add connected controller
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='CPU: ', In_Variable:=Int_Alarm[Wrk_AlarmReturn_Index].Sts_Connected_Controller); //Adds connected controller
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='', In_Variable:='$N');//Line shift
		 END_IF;
		 
		 IF Ext_Settings.EXT_Engineering.Cfg_SMS_Include_TimeStamp THEN //IF config to add connected controller
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='Time: ', In_Variable:=Wrk_TimeStamp, Cfg_Order:=FALSE); //Adds timestamp
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='', In_Variable:='$N');//Line shift
		 END_IF;
		 
		 IF Ext_Settings.EXT_Engineering.Cfg_SMS_Include_Location THEN //IF config to add connected controller
			 
			 FOR LocationIndex_LookUp:= DINT_TO_UINT(LOWER_BOUND(Ext_Settings.EXT_Engineering.Location_Data,1)) TO DINT_TO_UINT(UPPER_BOUND(Ext_Settings.EXT_Engineering.Location_Data,1)) DO
				 IF Ext_Settings.EXT_Engineering.Location_Data[LocationIndex_LookUp].InUse AND Ext_Settings.EXT_Engineering.Location_Data[LocationIndex_LookUp].ID = Int_Alarm[Wrk_AlarmReturn_Index].Sts_Location[0] THEN //Location array[0] is main location
					 LocationName:=Ext_Settings.EXT_Engineering.Location_Data[LocationIndex_LookUp].Name;
					 EXIT;
				 END_IF;
			 END_FOR;
			 
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='Loc: ', In_Variable:= LocationName); //Adds connected location
			 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='', In_Variable:='$N');//Line shift
		 END_IF;
		 
		 HE_StrConcatAdv(InOut:=Wrk_SMS_Message, In_Static:='Al: ', In_Variable:= NumToDecString(In:=Wrk_AlarmReturn_Index, L:=3, Fill:=_ZERO)); //Adds alarm number
		
		 // Trigger Send SMS
		 IF NOT FB_RT100_SMS.Sts_SendSMSBusy AND Wrk_SMS_Message<>'' AND  Wrk_SMS_SendBuffer_PhoneNumber[0] <>'' THEN
			 Wrk_State := 20;
			 Wrk_TimeInState := T#0s;
			 FB_RT100_SMS.Inp_SendSMS := TRUE;
			 
		 //No message generated, or no reciver found
		 ELSIF Wrk_SMS_Message='' OR  Wrk_SMS_SendBuffer_PhoneNumber[0] = '' THEN
			 Wrk_State := 31;
			 Wrk_TimeInState := T#0s;		 
			
		 // State Timeout
		 ELSIF Wrk_TimeInState > T#60s THEN
			 Wrk_State := 31;
			 Wrk_TimeInState := T#0s;
		 END_IF;	 	 
		 
	(**************************************************************************
	*	SENDING ACTIVE - WAITING CONFIRMATION
    **************************************************************************) 
	20: 
		//Sending sucsessfull
		 IF FB_RT100_SMS.Sts_SendSMSDone THEN
			 FB_RT100_SMS.Inp_SendSMS := FALSE;
			 IF Wrk_AlarmSend_Found THEN
				Wrk_State := 30;
			 ELSIF Ext_Settings.EXT_Operator.Cfg_Emergency_Send THEN
				Wrk_State := 0;
				Ext_Settings.EXT_Operator.Cfg_Emergency_Send:=FALSE;
			 ELSIF Wrk_SendAcknMessage THEN
				 Wrk_State := 0;
				 Wrk_SendAcknMessage:=FALSE;
			 ELSIF Wrk_AlarmReturn_Found THEN
				 Wrk_State := 0;
				 Wrk_AlarmReturn_Found:=FALSE;
			 END_IF;
				Wrk_TimeInState := T#0s;
				
		//Sending faulted/error
		ELSIF FB_RT100_SMS.Sts_SendSMSError THEN
		 	Wrk_State := 31;
			Wrk_TimeInState := T#0s;
			
		 ELSIF Wrk_TimeInState > T#60s THEN
			 Wrk_State := 31;
			 Wrk_TimeInState := T#0s;
		 END_IF;
	
	(************************************************************************************
	*	SEND SUCSESS - INCREMENT TIME TO NEXT PRIORITY (Only alarm message)
   *************************************************************************************) 
	30:
			Inc(Int_Alarm[Wrk_AlarmSend_Index].Sts_AlarmData[Wrk_AlarmSend_Number].SMS_AlarmState); //Increment alarm state
			 IF Ext_Settings.EXT_Engineering.Sts_DayShift_Active THEN //IF day shift active
			 	Int_Alarm[Wrk_AlarmSend_Index].Sts_AlarmData[Wrk_AlarmSend_Number].SMS_TimeToNextPri := SecToTime(Ext_Settings.EXT_Engineering.Cfg_DayShift_Delay*60); //Adds day shift to alarm variabel (time to next sending)
			 ELSIF Ext_Settings.EXT_Engineering.Sts_NightShift_Active THEN //IF night shift active
				 Int_Alarm[Wrk_AlarmSend_Index].Sts_AlarmData[Wrk_AlarmSend_Number].SMS_TimeToNextPri := SecToTime(Ext_Settings.EXT_Engineering.Cfg_NightShift_Delay*60); //Adds night shift to alarm variabel (time to next sending)
			 END_IF;
			 
			 Wrk_AlarmSend_Found:=FALSE;
			 Wrk_State := 0;
			 Wrk_TimeInState := T#0s;
	
	(************************************************************************************
	*	SEND ERROR - RETRY COUNT INCREMENT (If >3 - Reset)
    *************************************************************************************) 
	31: 
			Inc(Wrk_SMS_Snd_RetryCount); //Increment retry count (3 retry before fault)
			
			//Retry count used
			 IF Wrk_SMS_Snd_RetryCount >= 3 THEN
				 Wrk_SMS_Snd_RetryCount:=0;
				 Wrk_State := 0;
				 Wrk_TimeInState := T#0s;
				 FB_RT100_SMS.Inp_SendSMS := FALSE;
				 Ext_Settings.EXT_Operator.Cfg_Emergency_Send:=FALSE;
				 Wrk_SendAcknMessage:=FALSE;
				 Wrk_AlarmReturn_Found:=FALSE;
				 
				 //IF alarm message - Set to suscess and stop sending
				 IF Wrk_AlarmSend_Found THEN
					 Wrk_State := 30;
				 	Wrk_TimeInState := T#0s;
				 END_IF;
				
			//Try again	
			 ELSE
				Wrk_State := 0;
			 	Wrk_TimeInState := T#0s;
			 END_IF;
	
 END_CASE;
 
 // Increment state time
 Wrk_TimeInState :=  ADD_TIME(In1:=Wrk_TimeInState, In2:=Wrk_TaskIntervalTime);
 
 (*************************************************************************
 * ACKNOWLEDGE ALARM FROM SMS
 *************************************************************************)
//Looking through internal/external variable structure. Messages is received to the master controller to modem
	
IF NOT Wrk_SendAcknMessage THEN
	Wrk_LB:=DINT_TO_UINT(LOWER_BOUND(Ext_Settings.INT_Data.IncommingMessage, 1));
	Wrk_UB:=DINT_TO_UINT(UPPER_BOUND(Ext_Settings.INT_Data.IncommingMessage, 1));
	Clear(Wrk_SendAcknMessage_Message);
	Clear(Wrk_SendAcknMessage_Number);

	FOR Wrk_Rec_ArrayPos:=Wrk_LB TO Wrk_UB DO //FOR loop through buffer array of incomming messages
			
			//CURRENT INDEX NOT SET TO DELETE AND CONTAIN MESSAGE
			//----------------------------------------------------------------------
			IF NOT Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Sts_Delete //Recive position not set to be deleted
				AND Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Message <> '' //Recive message contains text
				AND FIND(In1 := Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Message, In2 := CONCAT('Agent: ',Cfg_Indentification)) > 0 //Identification matching FB input "Cfg_Identification"
				AND FIND(In1 := Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Message, In2 :='Al: ') > 0 THEN	//Al: found (message contains alarm number
				
				Wrk_SMS_Rec_AlarmIndex := 	STRING_TO_UINT(MID(In:=Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Message, //Read from message in current index
																										L:=3, //Read 3 length (Alarm numer xxx)
																										P:= FIND(In1 := Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Message, In2 :='Al: ') + LEN('Al: '),
																										ENO => Wrk_SMS_Rec_AlarmIndexFound));
				
				//IDENTIFICATION MACHING & ALARM NUMBER FOUND
				//--------------------------------------------------------------
				Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Sts_Delete:=TRUE; // Delete entry (current recive position belog to this controller)
				//Reset variables before loop
				Wrk_SMS_Rec_ContactFound:=FALSE;
				Wrk_SMS_Rec_AlarmFound:=FALSE;
				
				//Looks for matching number in contact list
				FOR Wrk_SMS_Rec_ContactPos := DINT_TO_UINT(LOWER_BOUND(Ext_Contacts ,1)) TO DINT_TO_UINT(UPPER_BOUND(Ext_Contacts,1)) DO //FOR loop through contact list (check that sender is listed)
					
					IF FIND( Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Number , Ext_Contacts[Wrk_SMS_Rec_ContactPos].Cfg_PhoneNumber) >0 THEN //Looking for phone number
						Wrk_SMS_Rec_ContactFound:=TRUE;
						EXIT;
					END_IF;
				END_FOR;	
						
				//Looking for matching suffix (find alarm number)			
				FOR Wrk_SMS_Rec_AlarmNumber:= DINT_TO_UINT(LOWER_BOUND(Int_Alarm[Wrk_SMS_Rec_AlarmIndex].Sts_AlarmData, 1)) TO DINT_TO_UINT(UPPER_BOUND(Int_Alarm[Wrk_SMS_Rec_AlarmIndex].Sts_AlarmData, 1)) DO //Looking for matching suffix
					
					IF FIND(In1 :=Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Message , In2 :=Int_Alarm[Wrk_SMS_Rec_AlarmIndex].Sts_AlarmData[Wrk_SMS_Rec_AlarmNumber].SMS_Suffix) > 0 THEN
						Wrk_SMS_Rec_AlarmFound:=TRUE;
						EXIT;
					END_IF;
				END_FOR;
				
				//BUILDING MESSAGE - BASED ON CURRENT ALARM STATUS AND IDENTIFICATION
				//-------------------------------------------------------------------------------------------
				IF Wrk_SMS_Rec_ContactFound 
					AND Wrk_SMS_Rec_AlarmFound 
					AND Wrk_SMS_Rec_AlarmIndexFound 
					AND Int_Alarm[Wrk_SMS_Rec_AlarmIndex].Sts_AlarmData[Wrk_SMS_Rec_AlarmNumber].SMS_AlarmState > 0 
					AND Int_Alarm[Wrk_SMS_Rec_AlarmIndex].Sts_AlarmData[Wrk_SMS_Rec_AlarmNumber].SMS_AlarmState < 10 
					AND Ext_Settings.EXT_Engineering.Sts_DayShift_Active THEN
					
						Int_Alarm[Wrk_SMS_Rec_AlarmIndex].Sts_AlarmData[Wrk_SMS_Rec_AlarmNumber].SMS_TimeToNextPri := SecToTime(Ext_Settings.EXT_Engineering.Cfg_DayShift_DelayAcknowledged*60); //Adds day shift to alarm variabel (time to next sending)
						Wrk_SendAcknMessage:=TRUE;
						HE_StrConcatAdv(InOut:=Wrk_SendAcknMessage_Message, In_Static:='Message recived. Next send delayed by ', In_Variable:=UINT_TO_STRING(Ext_Settings.EXT_Engineering.Cfg_DayShift_DelayAcknowledged));
						HE_StrConcatAdv(InOut:=Wrk_SendAcknMessage_Message, In_Static:='min', In_Variable:='');
						Wrk_SendAcknMessage_Number:= Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Number;
				
				ELSIF Wrk_SMS_Rec_ContactFound 
					AND Wrk_SMS_Rec_AlarmFound 
					AND Wrk_SMS_Rec_AlarmIndexFound 
					AND Int_Alarm[Wrk_SMS_Rec_AlarmIndex].Sts_AlarmData[Wrk_SMS_Rec_AlarmNumber].SMS_AlarmState > 0 
					AND Int_Alarm[Wrk_SMS_Rec_AlarmIndex].Sts_AlarmData[Wrk_SMS_Rec_AlarmNumber].SMS_AlarmState < 10 
					AND Ext_Settings.EXT_Engineering.Sts_NightShift_Active THEN
					 	
						 Int_Alarm[Wrk_SMS_Rec_AlarmIndex].Sts_AlarmData[Wrk_SMS_Rec_AlarmNumber].SMS_TimeToNextPri := SecToTime(Ext_Settings.EXT_Engineering.Cfg_NightShift_DelayAcknowledged*60); //Adds night shift to alarm variabel (time to next sending)
						 Wrk_SendAcknMessage:=TRUE;
						 HE_StrConcatAdv(InOut:=Wrk_SendAcknMessage_Message, In_Static:='Message recived. Next send delayed by ', In_Variable:=UINT_TO_STRING(Ext_Settings.EXT_Engineering.Cfg_NightShift_DelayAcknowledged));
						 HE_StrConcatAdv(InOut:=Wrk_SendAcknMessage_Message, In_Static:='min', In_Variable:='');
						 Wrk_SendAcknMessage_Number:=Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Number;

					 
				ELSIF Wrk_SMS_Rec_ContactFound 
					AND Wrk_SMS_Rec_AlarmFound  
					AND Wrk_SMS_Rec_AlarmIndexFound 
					AND Int_Alarm[Wrk_SMS_Rec_AlarmIndex].Sts_AlarmData[Wrk_SMS_Rec_AlarmNumber].SMS_AlarmState = 10  THEN//Alarm acknowleged
					
					 Wrk_SendAcknMessage:=TRUE;
					 Wrk_SendAcknMessage_Message:= 'Message recived. Alarm was already acknowleged';
					 Wrk_SendAcknMessage_Number:=Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Number;	
				 
				ELSIF Wrk_SMS_Rec_ContactFound 
					AND Wrk_SMS_Rec_AlarmFound  
					AND Wrk_SMS_Rec_AlarmIndexFound 
					AND Int_Alarm[Wrk_SMS_Rec_AlarmIndex].Sts_AlarmData[Wrk_SMS_Rec_AlarmNumber].SMS_AlarmState = 0  THEN//Alarm no longer active
					
					 Wrk_SendAcknMessage:=TRUE;
					 Wrk_SendAcknMessage_Message:= 'Message recived. Alarm no longer active';
					 Wrk_SendAcknMessage_Number:=Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Number;	
				 
				ELSIF NOT Wrk_SMS_Rec_ContactFound THEN //Number not found in contact list
					
					 Wrk_SendAcknMessage:=TRUE;
					 Wrk_SendAcknMessage_Message:= 'Message recived. Could not find your number in contact list';
					 Wrk_SendAcknMessage_Number:=Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Number;	
				 
				 ELSIF NOT Wrk_SMS_Rec_AlarmFound THEN//Alarm not found
					 
					 Wrk_SendAcknMessage:=TRUE;
					 Wrk_SendAcknMessage_Message:= 'Message recived. Could not find maching alarm';
					 Wrk_SendAcknMessage_Number:=Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Number;	
				 
				ELSIF NOT Wrk_SMS_Rec_AlarmIndexFound THEN//Alarm not found
					
					 Wrk_SendAcknMessage:=TRUE;
					 Wrk_SendAcknMessage_Message:= 'Message recived. Could not find maching suffix';
					 Wrk_SendAcknMessage_Number:=Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayPos].Number;	
				 
				END_IF;
			END_IF;
	END_FOR;
END_IF;
			
 (*************************************************************************
 * MASTER CONTROL
 *************************************************************************)

//READ MODEM STATUS
//---------------------------------
FB_RT100_Status(ENI:=Cfg_CheckStatus, 
						 Cfg_IP_Adresse:=Cfg_IP_Adress, 
						 Cfg_Port:=UINT#443, 
						 Cfg_TLSSession:=Cfg_TLSSession, 
						 Cfg_CheckInterval:=Cfg_Master_ReadState_Interval, 
						 Cfg_Timeout:=TIME#10s);

//SEND AND RECIVE SMS
//---------------------------------
 FB_RT100_SMS(ENI:=TRUE, 
							 Ext_PhoneNumbers:=Wrk_SMS_SendBuffer_PhoneNumber, 
							 Inp_Message:=Wrk_SMS_Message,
							 Cfg_IP_Adresse:=Cfg_IP_Adress,
							 Cfg_CheckInbox := Cfg_CheckInbox);

(*************************************************************************
 *	CONTROL OF INCOMMING MESSAGE STACK
 *************************************************************************)

// Push incomming message on recieve stack
IF FB_RT100_SMS.Sts_RecvSMS_New THEN
	
	Wrk_LB:=DINT_TO_UINT(LOWER_BOUND(Ext_Settings.INT_Data.IncommingMessage, 1));
	Wrk_UB:=DINT_TO_UINT(UPPER_BOUND(Ext_Settings.INT_Data.IncommingMessage, 1));
	
	FOR  Wrk_Rec_ArrayContr := Wrk_LB TO Wrk_UB DO //Find available index
		IF Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayContr].Message = '' AND Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayContr].Number = '' AND NOT Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayContr].Sts_Delete THEN
			Ext_Settings.INT_Data.IncommingMessage[Wrk_LB].Message := FB_RT100_SMS.Out_RecvSMS_Message;
			Ext_Settings.INT_Data.IncommingMessage[Wrk_LB].Number := FB_RT100_SMS.Out_RecvSMS_FromAddress;
			
			Wrk_TimestampDT.Year:=		STRING_TO_UINT(MID(In:=		FB_RT100_SMS.Out_RecvSMS_DateTime, L:=2, P:=1))+2000; 		//Parse year
			Wrk_TimestampDT.Month:=	STRING_TO_USINT(MID(In:=	FB_RT100_SMS.Out_RecvSMS_DateTime, L:=2, P:=4)); 					//Parse month
			Wrk_TimestampDT.Day:=		STRING_TO_USINT(MID(In:=	FB_RT100_SMS.Out_RecvSMS_DateTime, L:=2, P:=7));	 				//Parse day
			Wrk_TimestampDT.Hour:=		STRING_TO_USINT(MID(In:=	FB_RT100_SMS.Out_RecvSMS_DateTime, L:=2, P:=10)); 	 				//Parse hour
			Wrk_TimestampDT.Min:=		STRING_TO_USINT(MID(In:=	FB_RT100_SMS.Out_RecvSMS_DateTime, L:=2, P:=13)); 	 				//Parse minute
			Wrk_TimestampDT.Sec:=			STRING_TO_USINT(MID(In:=	FB_RT100_SMS.Out_RecvSMS_DateTime, L:=2, P:=16)); 	 				//Parse second
			Ext_Settings.INT_Data.IncommingMessage[Wrk_LB].DateTime:= DateStructToDt(Wrk_TimestampDT);

			FB_RT100_SMS.Inp_RecvSMSAck:= TRUE; //Resets "New message" ouput from FB
			
			EXIT;
		END_IF;
	END_FOR;
ELSE
	
	FB_RT100_SMS.Inp_RecvSMSAck:=FALSE;
END_IF;

//Array control
IF Cfg_CheckInbox THEN
	Wrk_LB:=DINT_TO_UINT(LOWER_BOUND(Ext_Settings.INT_Data.IncommingMessage, 1));
	Wrk_UB:=DINT_TO_UINT(UPPER_BOUND(Ext_Settings.INT_Data.IncommingMessage, 1));
	FOR  Wrk_Rec_ArrayContr := Wrk_LB TO Wrk_UB DO
		
		//SET DELETE - IF IDENTIFICATION NOT FOUND
		//--------------------------------------------------
		IF Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayContr].Message <> '' OR Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayContr].Number <> '' THEN
			IF  	  FIND(Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayContr].Message,'Agent: ') = 0 		//Agent identifier not found
				OR FIND(Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayContr].Message,'Al: ') = 0 			//Alarm number not found
				OR Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayContr].Message = ''					  			//Incomming message contains text
				OR Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayContr].Number = ''					  			//Incomming number contains text
				OR SUB_DT_DT(Date_Current, DateStructToDt(Wrk_TimestampDT)) > Cfg_InboxMaxAge THEN			//Age too high

				Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayContr].Sts_Delete:= 	TRUE;
			END_IF;
		END_IF;
		
		//CLEAR ENTRY - IF DELETE -> TRUE
		//--------------------------------------
		IF Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayContr].Sts_Delete THEN
			Clear(Ext_Settings.INT_Data.IncommingMessage[Wrk_Rec_ArrayContr]);
		END_IF;
	END_FOR;
END_IF;
	
 (*************************************************************************
 * LOCAL NOTIFICATION (light and siren)
 *************************************************************************)	
 
 TOF_Siren(PT:= SecToTime(Ext_Settings.EXT_Engineering.Cfg_SirenTime));
 
 IF Wrk_NumAlarmActive > Wrk_NumAlarmActive_Sample THEN
	 TOF_Siren.In:=TRUE;
	 Wrk_NumAlarmActive_Sample:=Wrk_NumAlarmActive;
 ELSIF Wrk_NumAlarmActive < Wrk_NumAlarmActive_Sample THEN
	 Wrk_NumAlarmActive_Sample:=Wrk_NumAlarmActive;
	 TOF_Siren.In:=FALSE;
 ELSE
	 TOF_Siren.In:=FALSE;
 END_IF;

IF TOF_Siren.Q THEN
	
	Ext_Settings.INT_Data.Siren_General:=TRUE;
	
	CASE Int_Alarm[Wrk_AlarmSend_Index].Sts_AlarmData[Wrk_AlarmSend_Number].SMS_Priority OF 
		
		0://Diagnostic
		Ext_Settings.INT_Data.Siren_DiagnosticPri:=TRUE;
		
		1://Low
		Ext_Settings.INT_Data.Siren_LowPri:=TRUE;
		
		2://Medium
		Ext_Settings.INT_Data.Siren_MediumPri:=TRUE;
		
		3://High
		Ext_Settings.INT_Data.Siren_HighPri:=TRUE;
		
		4://Critical
		Ext_Settings.INT_Data.Siren_CriticalPri:=TRUE;
		
		5://Simulating
		Ext_Settings.INT_Data.Siren_DiagnosticPri:=TRUE;
		
		6://Good
		Ext_Settings.INT_Data.Siren_DiagnosticPri:=TRUE;
		
	END_CASE;
	
ELSE //Timer complete
	Ext_Settings.INT_Data.Siren_General:=FALSE;
	Ext_Settings.INT_Data.Siren_DiagnosticPri:=FALSE;
	Ext_Settings.INT_Data.Siren_LowPri:=FALSE;
	Ext_Settings.INT_Data.Siren_MediumPri:=FALSE;
	Ext_Settings.INT_Data.Siren_HighPri:=FALSE;
	Ext_Settings.INT_Data.Siren_CriticalPri:=FALSE;
END_IF;

Ext_Settings.INT_Data.Light := Wrk_NumAlarmActive > 0;

(*************************************************************************
 *	BACKUP SENDER - (Usually alarm dailer)
 *************************************************************************)

Ext_Settings.EXT_General.Cfg_BackupSend_Visible:=Cfg_BackupSending_InUse;
	
//SOMETHING MISSING HERE	
	
(*************************************************************************
 *	STATISTICS
 *************************************************************************)
 
RE_SMSSend(Clk:=FB_RT100_SMS.Inp_SendSMS);	
	
IF RE_SMSSend.Q THEN	
	Inc(Ext_Settings.EXT_Statistics.NumberSendt_Today);
END_IF;

IF DayOfWeek_Current <> DayOfWeek_Sample THEN
	Ext_Settings.EXT_Statistics.NumberSendt_Yesterday := Ext_Settings.EXT_Statistics.NumberSendt_Today;
	Clear(Ext_Settings.EXT_Statistics.NumberSendt_Today);
END_IF;

DayOfWeek_Sample :=DayOfWeek_Current;

(*************************************************************************
 *	UPDATES OUTPUT & STRUCTURE
 *************************************************************************)

//BLOCK OUTPUT
Sts_AlarmArrayOutOfRange:=	Wrk_AlarmArrayOutOfRange;
Sts_NumAlarmUsed:=				Wrk_NumberAlarmUsed;
Sts_ConnectionError := 			Ext_Settings.EXT_General.Sts_Modem_Fault;
Sts_NumActiveAlarms:= 			Wrk_NumAlarmActive;
Sts_NumAcknAlarms:= 			Wrk_NumAlarmAck;

//STRUCTURE UPDATE
Ext_Settings.EXT_General.Sts_Modem_LinkState :=				FB_RT100_Status.Out_LinkState;
Ext_Settings.EXT_General.Sts_Modem_Operator := 			FB_RT100_Status.Out_Operator;
Ext_Settings.EXT_General.Sts_Modem_NetworkMode := 	FB_RT100_Status.Out_WirelessGen;
IF FB_RT100_Status.Out_Signal <> 99 THEN
	Ext_Settings.EXT_General.Sts_Modem_SignalStrength := 	ScaleTrans(SclIn:=DINT_TO_REAL(FB_RT100_Status.Out_Signal), 
																											 X0:=0, 
																											 Y0:=0, 
																											 X1:=31, 
																											 Y1:=100);
ELSE
	Ext_Settings.EXT_General.Sts_Modem_SignalStrength :=	0;
END_IF;

Ext_Settings.EXT_General.Sts_Modem_Fault :=	FB_RT100_Status.Sts_ConnectionError
																			OR Cfg_IP_Adress = ''
																			OR Cfg_TLSSession = ''
																			OR Cfg_Indentification = ''
																			OR FB_RT100_Status.Out_Signal = 0
																			OR FB_RT100_Status.Out_Signal = 99;
